    public void FocusIta(ItaEntry? entry){if(entry==null)return;target=ItaWorld(entry);float radius=3f;if(itmCatalog?.ModelParts.TryGetValue(entry.ItemId,out var parts)==true){var points=parts.SelectMany(p=>p.Triangles).SelectMany(t=>new[]{TransformIta(t.A,entry),TransformIta(t.B,entry),TransformIta(t.C,entry)}).ToArray();if(points.Length>0){var min=points.Aggregate(new System.Numerics.Vector3(float.PositiveInfinity),System.Numerics.Vector3.Min);var max=points.Aggregate(new System.Numerics.Vector3(float.NegativeInfinity),System.Numerics.Vector3.Max);target=(min+max)*.5f;radius=Math.Max(1f,(max-min).Length()*.5f);}}distance=Math.Clamp(radius*2.8f,8f,5000f);cameraPosition=target-GetForward()*distance;Invalidate();}

    private void UploadIta()
    {
        itaGpuDirty=false;itaCount=itaSelectedCount=itaModelCount=itaSelectedModelCount=0;if(!glReady||itaScene==null)return;EnsureItaBuffers();
        var normal=new List<float>();var selected=new List<float>();var gizmos=new[]{new List<float>(),new List<float>(),new List<float>()};
        var models=new Dictionary<ItaTextureKey,List<float>>();var selectedModels=new Dictionary<ItaTextureKey,List<float>>();
